-- Omni-Channel Green Start rebuild (2026-10-17): Templates page (RCS assistants and templates, WhatsApp Flows, voice scripts) and Content Studio (saved content).
-- Raw-SQL tables, no Prisma model; the app also creates them itself with IF NOT EXISTS the first time the page is used (outreach/tplOwn.js, outreach/studio.js).
-- COLUMNS ARE NOT IN THIS FILE ON PURPOSE (SQLite has no ADD COLUMN IF NOT EXISTS; the app adds them itself, guarded by PRAGMA table_info):
--   OutreachTemplate  category, extra   (extra = JSON of the WhatsApp / email layout: header, footer, buttons, call permission, review and Meta records; added through outreach/v3schema.js)
CREATE TABLE IF NOT EXISTS "OmniRcsAgent" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'saved', "data" TEXT NOT NULL DEFAULT '{}', "audience" TEXT NOT NULL DEFAULT 'candidate_lead', "department" TEXT, "createdById" TEXT, "createdByName" TEXT, "createdAt" DATETIME NOT NULL DEFAULT 0, "updatedAt" DATETIME NOT NULL DEFAULT 0, "deletedAt" DATETIME);
CREATE TABLE IF NOT EXISTS "OmniRcsTemplate" ("id" TEXT NOT NULL PRIMARY KEY, "agentId" TEXT NOT NULL, "name" TEXT NOT NULL, "type" TEXT NOT NULL DEFAULT 'text', "status" TEXT NOT NULL DEFAULT 'draft', "form" TEXT NOT NULL DEFAULT '{}', "audience" TEXT NOT NULL DEFAULT 'candidate_lead', "department" TEXT, "createdById" TEXT, "createdByName" TEXT, "createdAt" DATETIME NOT NULL DEFAULT 0, "updatedAt" DATETIME NOT NULL DEFAULT 0, "deletedAt" DATETIME);
CREATE INDEX IF NOT EXISTS "OmniRcsTemplate_agent" ON "OmniRcsTemplate"("agentId", "updatedAt");
CREATE TABLE IF NOT EXISTS "OmniWaFlow" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'saved', "screens" TEXT NOT NULL DEFAULT '[]', "audience" TEXT NOT NULL DEFAULT 'candidate_lead', "department" TEXT, "createdById" TEXT, "createdByName" TEXT, "createdAt" DATETIME NOT NULL DEFAULT 0, "updatedAt" DATETIME NOT NULL DEFAULT 0, "deletedAt" DATETIME);
CREATE TABLE IF NOT EXISTS "OmniVoiceScript" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "category" TEXT NOT NULL DEFAULT 'Utility', "language" TEXT, "script" TEXT NOT NULL DEFAULT '', "audio" TEXT, "status" TEXT NOT NULL DEFAULT 'active', "audience" TEXT NOT NULL DEFAULT 'candidate_lead', "department" TEXT, "createdById" TEXT, "createdByName" TEXT, "createdAt" DATETIME NOT NULL DEFAULT 0, "updatedAt" DATETIME NOT NULL DEFAULT 0, "deletedAt" DATETIME);
CREATE TABLE IF NOT EXISTS "OmniStudioContent" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "voice" TEXT, "cta" TEXT, "master" TEXT NOT NULL DEFAULT '', "subject" TEXT, "adaptations" TEXT NOT NULL DEFAULT '{}', "libraryIds" TEXT NOT NULL DEFAULT '[]', "department" TEXT, "status" TEXT NOT NULL DEFAULT 'ready', "createdById" TEXT, "createdByName" TEXT, "createdAt" DATETIME NOT NULL DEFAULT 0, "updatedAt" DATETIME NOT NULL DEFAULT 0, "deletedAt" DATETIME);
CREATE INDEX IF NOT EXISTS "OmniStudioContent_name" ON "OmniStudioContent"("name");
